#!/usr/bin/env python3
"""Versioned L35 quality repairs by a distinct contributor. No independent approvals."""
import json,copy,hashlib
from pathlib import Path
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[1];B='W07-L35';A='L35-repair-author-20261019'
def read(p):return json.loads((R/p).read_text())
def write(p,x):(R/p).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def qhash(q):return hashlib.sha256(json.dumps({k:v for k,v in q.items() if k not in ('status','reviewIds')},sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()).hexdigest()
def fhash(p):return hashlib.sha256((R/p).read_bytes()).hexdigest()
if (R/f'audits/{B}-v2-review-manifest.json').exists():raise SystemExit('Frozen v2. Do not overwrite reviewed content.')
old=read(f'data/question-batches/archive/{B}-v1.json');b=copy.deepcopy(old);qm={q['id']:q for q in b['questions']}
rv=read(f'data/reviews/{B}-v1-independent.json');flags={r['questionId']:r for r in rv if r['decision']=='flagged'}
assert len(flags)==87 and len(old['questions'])==98
accepted=[q for q in old['questions'] if q['id'] not in flags];assert len(accepted)==11
for q in accepted:assert any(r['questionId']==q['id'] and r['decision']=='verified' and r['questionSha256']==qhash(q) for r in rv)
for qid,r in flags.items():
 q=qm[qid];assert q['version']==r['questionVersion'] and qhash(q)==r['questionSha256']
 q.update(version=q['version']+1,status='draft',reviewIds=[],difficulty='easy');q['revisionAuthors']=sorted(set(q.get('revisionAuthors',[])+[A]))
 if 'conflictResolution' in q:q['conflictResolution']['questionVersion']=q['version']
changed_sets=set()
def Q(n):return qm[f'{B}-Q{n:03d}']
def revise(n,rows,stem=None):
 q=Q(n);assert q['id'] in flags and q['correctOptionIds']==['o1'];assert len(rows)==4
 if stem:q['stem']=stem
 d={f'o{i+1}':r for i,r in enumerate(rows)}
 for o in q['options']:o['text']=d[o['id']][0]
 why={k:v[1] for k,v in d.items()}
 q['solution'].update(justification=why['o1'],simpleExplanation=why['o1'],optionExplanations={k:('Correct. 'if k=='o1'else'Incorrect. ')+v for k,v in why.items()},misconceptions=[why[k] for k in ('o2','o3','o4')]);changed_sets.add(q['id'])
def option(n,key,value,why):
 q=Q(n)
 next(o for o in q['options'] if o['id']==key)['text']=value;q['solution']['optionExplanations'][key]='Incorrect. '+why
 q['solution']['misconceptions']=[q['solution']['optionExplanations'][k] for k in ('o2','o3','o4')];changed_sets.add(q['id'])
